// DECISION LOG:
// 1. Map raw sheet columns to canonical workflow variables
// 2. Detect status change by comparing CurrentStatus vs PreviousStatus
// 3. Flag missing email (Error Type 1 detection)
// 4. Check digest cache to prevent duplicate notifications within 5-minute window
// 5. Weather cache: 3-hour TTL keyed by zip code

const staticData = $getWorkflowStaticData('global');
if (!staticData.digestCache) staticData.digestCache = {};
if (!staticData.weatherCache) staticData.weatherCache = {};

const now = Date.now();
const DIGEST_TTL_MS = 5 * 60 * 1000; // 5 minutes

const results = [];

for (const item of $input.all()) {
  const row = item.json;

  // Map CSV columns to canonical variables
  const csv_jobId = (row.JobID || '').trim();
  const csv_customerName = (row.CustomerName || '').trim();
  const csv_customerEmail = (row.CustomerEmail || '').trim();
  const csv_jobType = (row.JobType || '').trim();
  const csv_priority = (row.Priority || '').trim();
  const csv_status = (row.CurrentStatus || '').trim();
  const csv_previousStatus = (row.PreviousStatus || '').trim();
  const csv_zipCode = (row.InstallationZipCode || '').trim();

  // Skip if no status change detected
  if (csv_status === csv_previousStatus) {
    continue;
  }

  // Digest check: suppress if same JobID+Status seen within 5 min
  const digestKey = `${csv_jobId}_${csv_status}`;
  const lastSeen = staticData.digestCache[digestKey];
  const is_duplicate = lastSeen && (now - lastSeen) < DIGEST_TTL_MS;

  if (is_duplicate) {
    // Suppress — duplicate within window
    continue;
  }

  // Update digest cache
  staticData.digestCache[digestKey] = now;

  // Error Type 1: Missing email detection
  const has_missing_email = !csv_customerEmail || csv_customerEmail === '';

  // Email validation regex
  const emailValid = !has_missing_email && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(csv_customerEmail);

  // Routing flags
  const should_check_weather = csv_status === 'Scheduled';
  const should_send_slack = csv_priority === 'Urgent';
  const should_send_email = !has_missing_email && emailValid;

  // Zip code basic validation (5 digits)
  const zip_valid = /^\d{5}$/.test(csv_zipCode);
  const effective_zip = zip_valid ? csv_zipCode : '90210'; // fallback zip
  const zip_substituted = !zip_valid;

  results.push({
    json: {
      csv_jobId,
      csv_customerName,
      csv_customerEmail,
      csv_jobType,
      csv_priority,
      csv_status,
      csv_previousStatus,
      csv_zipCode,
      effective_zip,
      zip_substituted,
      has_missing_email,
      should_check_weather,
      should_send_slack,
      should_send_email,
      digestKey,
      processedAt: new Date().toISOString()
    }
  });
}

return results;

// Error Type 1: Missing Customer Email
// Prepare log entry for Issues sheet and alert payload
return $input.all().map(item => ({
  json: {
    Timestamp: new Date().toISOString(),
    ErrorType: 'MissingEmail',
    AffectedJobID: item.json.csv_jobId,
    Details: `Customer ${item.json.csv_customerName} has no email on record. Job type: ${item.json.csv_jobType}, Priority: ${item.json.csv_priority}, Status: ${item.json.csv_status}`,
    Resolution: 'Manual contact required',
    NotifiedManager: 'Y',
    DateResolved: '',
    // Pass-through for Slack alert
    csv_jobId: item.json.csv_jobId,
    csv_customerName: item.json.csv_customerName,
    csv_priority: item.json.csv_priority,
    csv_status: item.json.csv_status
  }
}));

