// DECISION LOG:
// Weather cache: 3-hour TTL keyed by zip code
// If cache hit and fresh (<3 hours): skip API call, reuse cached rain probability
// If cache miss or stale: flag for API call

const staticData = $getWorkflowStaticData('global');
if (!staticData.weatherCache) staticData.weatherCache = {};

const WEATHER_CACHE_TTL_MS = 3 * 60 * 60 * 1000; // 3 hours
const now = Date.now();

return $input.all().map(item => {
  const zip = item.json.effective_zip;
  const cached = staticData.weatherCache[zip];
  const cacheHit = cached && (now - cached.timestamp) < WEATHER_CACHE_TTL_MS;

  return {
    json: {
      ...item.json,
      weather_cache_hit: cacheHit,
      weather_rainProbability: cacheHit ? cached.rainProbability : null,
      weather_condition: cacheHit ? cached.condition : null,
      weather_from_cache: cacheHit
    }
  };
});

// DECISION LOG:
// Parse OpenWeatherMap 5-day/3-hour forecast response
// Extract max rain probability (pop) across first 8 windows (24 hours)
// Detect API errors: timeout, 404 (bad zip), 401 (bad key), 429 (rate limit)
// Store result in weather cache keyed by zip
// Apply fallback on any error condition

const staticData = $getWorkflowStaticData('global');
if (!staticData.weatherCache) staticData.weatherCache = {};

const results = [];

for (const item of $input.all()) {
  const response = item.json;
  const effectiveZip = response.effective_zip || response.csv_zipCode || 'unknown';
  const originalZip = response.csv_zipCode || effectiveZip;

  // Detect API-level errors (continueOnFail passes error object)
  const isApiError = response.error || response.statusCode >= 400 || !response.list;
  const isZipError = response.cod == '404' || (response.message && response.message.toLowerCase().includes('not found'));
  const isRateLimit = response.cod == '429' || response.statusCode == 429;
  const isAuthError = response.cod == '401' || response.statusCode == 401;

  let weather_rainProbability = 50; // fallback: conservative assumption
  let weather_condition = 'Unknown';
  let weather_api_error = false;
  let weather_error_type = null;
  let weather_error_detail = null;
  let weather_zip_substituted = response.zip_substituted || false;

  if (isZipError) {
    weather_api_error = true;
    weather_error_type = 'InvalidZip';
    weather_error_detail = `Zip code ${originalZip} not recognized by OpenWeatherMap. Used fallback zip ${effectiveZip}.`;
    // Default to conservative forecast
    weather_rainProbability = 50;
    weather_condition = 'Unknown';
  } else if (isRateLimit) {
    weather_api_error = true;
    weather_error_type = 'RateLimit';
    weather_error_detail = `OpenWeatherMap rate limit hit for zip ${effectiveZip}.`;
    weather_rainProbability = 50;
    weather_condition = 'Unknown';
  } else if (isAuthError) {
    weather_api_error = true;
    weather_error_type = 'WeatherAPIFailure';
    weather_error_detail = 'Invalid OpenWeatherMap API key (401).';
    weather_rainProbability = 50;
    weather_condition = 'Unknown';
  } else if (isApiError) {
    weather_api_error = true;
    weather_error_type = 'WeatherAPIFailure';
    weather_error_detail = `API error for zip ${effectiveZip}: ${JSON.stringify(response.error || response.message || 'timeout/unknown')}`;
    weather_rainProbability = 50;
    weather_condition = 'Unknown';
  } else {
    // Successful response — parse rain probability
    const forecastList = response.list || [];
    const windows = forecastList.slice(0, 8); // up to 24 hours
    // pop is 0–1 in the API, convert to 0–100
    const maxPop = windows.reduce((max, w) => {
      const pop = w.pop !== undefined ? w.pop : 0;
      const popPct = pop <= 1 ? pop * 100 : pop; // handle both formats
      return Math.max(max, popPct);
    }, 0);
    weather_rainProbability = Math.round(maxPop);
    weather_condition = (windows[0] && windows[0].weather && windows[0].weather[0])
      ? windows[0].weather[0].main
      : 'Clear';

    // Cache the result
    staticData.weatherCache[effectiveZip] = {
      timestamp: Date.now(),
      rainProbability: weather_rainProbability,
      condition: weather_condition
    };
  }

  results.push({
    json: {
      ...response,
      weather_rainProbability,
      weather_condition,
      weather_api_error,
      weather_error_type,
      weather_error_detail,
      weather_zip_substituted
    }
  });
}

return results;

// Error Types 2, 3, 5: Weather API Failure, Invalid Zip, Rate Limit
// Log entry and continue with fallback forecast
return $input.all().map(item => ({
  json: {
    Timestamp: new Date().toISOString(),
    ErrorType: item.json.weather_error_type || 'WeatherAPIFailure',
    AffectedJobID: item.json.csv_jobId,
    Details: item.json.weather_error_detail || 'Unknown weather API error',
    Resolution: 'Fallback forecast applied (50% rain probability). Manager notified.',
    NotifiedManager: 'Y',
    DateResolved: '',
    // Pass-through for alert and continuation
    csv_jobId: item.json.csv_jobId,
    csv_customerName: item.json.csv_customerName,
    csv_priority: item.json.csv_priority,
    csv_status: item.json.csv_status,
    csv_customerEmail: item.json.csv_customerEmail,
    csv_jobType: item.json.csv_jobType,
    csv_zipCode: item.json.csv_zipCode,
    effective_zip: item.json.effective_zip,
    weather_rainProbability: item.json.weather_rainProbability,
    weather_error_type: item.json.weather_error_type,
    should_send_slack: item.json.should_send_slack,
    should_send_email: item.json.should_send_email
  }
}));

